        StatusBannerText.Text = ok ? $"🔗 {msg}" : $"⚠️ {msg}";
        MessageBox.Show(this, msg, "Desktop Game Shortcut", MessageBoxButton.OK, ok ? MessageBoxImage.Information : MessageBoxImage.Warning);
