    private async void ExtractTrainerZipButton_OnClick(object sender, RoutedEventArgs e)
    {
        var dlg = new OpenFileDialog
        {
            Title = "Select Companion Trainer ZIP Archive",
            Filter = "ZIP Archives (*.zip)|*.zip|All Files (*.*)|*.*",
            DefaultExt = ".zip"
        };

